{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-webgl-liquid-iridescence",
  "title": "Liquid Iridescence",
  "title_i18n": {
    "zh-CN": "虹彩流体",
    "zh-TW": "虹彩流體",
    "ja": "リキッド・イリデッセンス",
    "ko": "리퀴드 이리데센스",
    "de": "Flüssige Iridiszenz",
    "fr": "Iridescence liquide",
    "ru": "Жидкая иридесценция",
    "es": "Iridiscencia líquida",
    "pt-BR": "Iridescência líquida",
    "en": "Liquid Iridescence"
  },
  "version": "0.1.0",
  "description": "A self-contained WebGL2 hero: a living oil-on-water field brightened into iridescent caustic filaments; move the cursor to bend the flow.",
  "description_i18n": {
    "zh-CN": "自包含 WebGL2 主视觉：活的油水场提亮为虹彩焦散丝线；移动光标扰动流场。",
    "zh-TW": "自包含 WebGL2 主視覺：活的油水場提亮為虹彩焦散絲線；移動游標擾動流場。",
    "en": "A self-contained WebGL2 hero: a living oil-on-water field brightened into iridescent caustic filaments; move the cursor to bend the flow."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/webgl-liquid-iridescence",
  "tags": [
    "example",
    "first-party",
    "hero",
    "webgl",
    "webgl2",
    "shader",
    "iridescent",
    "liquid",
    "generative",
    "powered-preview",
    "untitled"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "prototype",
    "scenario": "design",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Build a self-contained WebGL2 hero of a living oil-on-water iridescent field with caustic filaments, cursor-reactive.",
        "zh-CN": "构建自包含 WebGL2 主视觉：活的油水虹彩场加焦散丝线，光标可扰动。"
      }
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      }
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
